// Product improvements extend the existing workspace without replacing its data model.
pageNames.overview='Dashboard'; pageNames.subjects='Matières'; pageNames.account='Mon compte'; pageNames.ai='AI Planner';
iconFiles.ai='zap';
const aiNav=document.createElement('button');
aiNav.className='nav-item'; aiNav.dataset.page='ai';
aiNav.innerHTML='<span class="icon"></span>AI Planner';
document.querySelector('#mainNav').append(aiNav);
document.querySelectorAll('.nav-item').forEach(n=>n.innerHTML=`<span class="icon"></span>${pageNames[n.dataset.page]}`);
document.querySelectorAll('[data-action="profile"]').forEach(n=>{n.removeAttribute('data-action');n.dataset.go='account'});
document.querySelector('.notification-dot')?.remove();
document.querySelector('#notificationBtn').addEventListener('click',()=>{
 const due=state.tasks.filter(t=>!t.done&&t.date<=todayISO()).slice(0,5);
 document.querySelector('#notificationPanel').innerHTML='<strong>Échéances à suivre</strong>'+ (due.length?due.map(t=>`<p>${esc(t.title)} · ${t.date<todayISO()?'En retard':'Aujourd’hui'}</p>`).join('')+'<button class="link-btn" data-go="tasks">Voir mes tâches</button>':'<p>Aucune tâche en retard ou à terminer aujourd’hui.</p>');
});
const productOpenModal=openModal;
openModal=function(...args){productOpenModal(...args);document.querySelectorAll('#modalForm input[type="text"][required]').forEach(input=>{input.pattern='.*\\S.*';input.title='Saisissez au moins un caractère autre qu’un espace.'})};

function restoreRuntimeState(options={}){
 state.focusSettings={work:25,break:5,goal:4,subject:'',objective:'',...state.focusSettings};
 focusRun={mode:'work',duration:state.focusSettings.work*60,left:state.focusSettings.work*60,running:false,stamp:0,segments:{},subject:'',...state.focusRun};
 focusRun.segments||={};
 state.cnc={papers:{},...state.cnc}; state.cnc.papers||={};
 cncTimer={paperId:null,duration:14400,left:14400,running:false,stamp:0,...state.cnc.timer};
 if(!options.preserveView){
  cncView={screen:'filieres',filiere:null,subject:null,year:null};
  resetLearningSelection(); currentPage='overview'; selectedDay=todayISO();
 }
}
window.addEventListener('prepago:state-replaced',restoreRuntimeState);
window.addEventListener('prepago:pause-timers',()=>{
 settleFocus(); focusRun.running=false; persistFocus();
 settleCncTimer(); cncTimer.running=false; persistCnc();
});
restoreRuntimeState();
const settleFocusBase=settleFocus,settleCncBase=settleCncTimer;
settleFocus=function(...args){if(!document.body.classList.contains('auth-pending'))settleFocusBase(...args)};
settleCncTimer=function(...args){if(!document.body.classList.contains('auth-pending'))settleCncBase(...args)};
const persistFocusBase=persistFocus,persistCncBase=persistCnc;
persistFocus=function(){if(!document.body.classList.contains('auth-pending'))persistFocusBase()};
persistCnc=function(){if(!document.body.classList.contains('auth-pending'))persistCncBase()};

progressPercent=function(){const chapters=allChapters();return chapters.length?Math.round(chapters.reduce((n,c)=>n+chapterUnits(c),0)/(chapters.length*5)*100):0};
const renderOverviewBase=renderOverview;
function cleanDisplayName(value){return String(value||'').trim().replace(/\s+/g,' ').replace(/(^|[\s'-])\p{L}/gu,letter=>letter.toUpperCase())}
function greetingName(){const first=window.PrepagoAccount?.profile?.first_name;return cleanDisplayName(first||((state.profileName&&state.profileName!=='Préparationnaire')?state.profileName:''))}
renderOverview=function(){renderOverviewBase();const name=greetingName();document.querySelector('.dashboard-heading h1').textContent=name?`Bonjour, ${name}`:'Bonjour';};
const updateSidebarProductBase=updateSidebar;
updateSidebar=function(){updateSidebarProductBase();if(!state.profileName||state.profileName==='Préparationnaire'){document.querySelector('#sideProfileName').textContent='Mon compte';document.querySelector('#topbarProfileName').textContent='Mon compte';document.querySelector('.sidebar-avatar').textContent='P';document.querySelector('#topbarAvatar').textContent='P'}};

const taskRowBase=taskRow;
taskRow=function(t,editable=false){const priority={high:'Priorité haute',medium:'Priorité moyenne',low:'Priorité basse'}[t.priority]||'Priorité moyenne';return `<div class="desk-task ${t.done?'is-done':''}"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="Terminer : ${esc(t.title)}"><div class="task-copy"><strong>${esc(t.title)}</strong><div class="task-meta">${subjectBadge(t.subject)}${editable?`<span>${t.date===todayISO()?'Aujourd’hui':formatShort(t.date)}${t.time?' · '+esc(t.time):''}</span><span class="task-priority">${priority}</span>`:''}${!t.done&&t.date<todayISO()?'<span class="overdue">En retard</span>':''}</div></div>${t.minutes?`<span class="task-duration">≈ ${Number(t.minutes)} min</span>`:''}${editable?`<details class="action-menu"><summary aria-label="Actions pour ${esc(t.title)}">•••</summary><div><button type="button" data-task-edit="${esc(t.id)}">Modifier</button><button type="button" class="danger-action" data-task-remove="${esc(t.id)}">Supprimer</button></div></details>`:''}</div>`};
renderTasks=function(){
 let tasks=[...state.tasks].sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||''));
 if(taskView==='today')tasks=tasks.filter(t=>t.date===todayISO());
 if(taskView==='upcoming')tasks=tasks.filter(t=>!t.done&&t.date>todayISO());
 if(taskView==='open')tasks=tasks.filter(t=>!t.done);
 if(taskView==='done')tasks=tasks.filter(t=>t.done);
 document.querySelector('#page').innerHTML=header('Tâches','Tes priorités et tes échéances, au même endroit.',`<button class="primary-btn" data-task-new>+ Ajouter une tâche</button>`)+`<div class="view-tabs">${[['all','Toutes'],['today','Aujourd’hui'],['upcoming','À venir'],['open','À faire'],['done','Terminées']].map(([v,l])=>`<button data-task-view="${v}" class="${taskView===v?'active':''}" aria-pressed="${taskView===v}">${l}</button>`).join('')}</div><section class="task-surface">${tasks.map(t=>taskRow(t,true)).join('')||emptyState('check','Aucune tâche pour le moment','Ajoute ton prochain objectif pour commencer.','<button class="primary-btn" data-task-new>+ Ajouter une tâche</button>')}</section>`;
};
const renderCalendarBase=renderCalendar;
renderCalendar=function(){renderCalendarBase();document.querySelector('.day-agenda').insertAdjacentHTML('beforeend','<button class="secondary-btn" data-calendar-task>+ Ajouter une tâche ce jour</button>')};
const renderSubjectsBase=renderSubjects;
renderSubjects=function(){
 renderSubjectsBase();
 document.querySelectorAll('.subject-hub-card').forEach(card=>{const id=card.querySelector('[data-open-learning-subject]')?.dataset.openLearningSubject,s=state.subjects.find(item=>item.id===id);card.querySelector('.subject-hub-delete')?.remove();if(s)card.insertAdjacentHTML('beforeend',`<details class="action-menu subject-menu"><summary aria-label="Actions pour ${esc(s.name)}">•••</summary><div><button type="button" data-rename-subject="${esc(s.id)}">Renommer</button><button type="button" class="danger-action" data-delete-subject="${esc(s.id)}">Supprimer</button></div></details>`)});
 if(learningSubjectId){
  document.querySelector('#page .section-head')?.insertAdjacentHTML('beforeend',`<button class="secondary-btn" data-rename-subject="${esc(learningSubjectId)}">Renommer la matière</button>`);
  document.querySelectorAll('[data-chapter-card]').forEach(card=>{const head=card.querySelector('.chapter-card-head'),remove=head.querySelector('[data-remove-learning-chapter]'),chapterId=card.dataset.chapterCard;remove?.remove();head.insertAdjacentHTML('beforeend',`<details class="action-menu"><summary aria-label="Actions du chapitre">•••</summary><div><button type="button" data-rename-chapter="${esc(chapterId)}">Renommer</button><button type="button" data-organize-chapter="${esc(chapterId)}" data-subject-id="${esc(learningSubjectId)}">Changer de classement</button><button type="button" class="danger-action" data-remove-learning-chapter="${esc(chapterId)}" data-subject-id="${esc(learningSubjectId)}">Supprimer</button></div></details>`)});
 }
};
renderFocus=function(){
 const settings=state.focusSettings,locked=focusRun.running||focusRun.left<focusRun.duration,todaySessions=state.focusSessions.filter(s=>s.date===todayISO()).slice().reverse();
 document.querySelector('#page').innerHTML=header('Concentration','Choisis ton rythme. Le reste peut attendre.')+`<div class="focus-layout polished-focus"><section class="card focus-main"><div class="focus-toolbar"><div class="mode-switch" aria-label="Type de session"><button class="${focusRun.mode==='work'?'active':''}" data-focus-mode="work" ${locked?'disabled':''}>Étude</button><button class="${focusRun.mode==='break'?'active':''}" data-focus-mode="break" ${locked?'disabled':''}>Pause</button></div><div class="focus-presets">${[15,25,45,60].map(n=>`<button class="secondary-btn ${focusRun.mode==='work'&&settings.work===n?'active':''}" data-focus-preset="${n}" ${locked?'disabled':''}>${n} min</button>`).join('')}</div></div><div class="timer-surface"><div class="timer-ring" id="focusRing"><div><div class="timer-display" id="focusClock"></div><div class="timer-label">${focusRun.mode==='work'?'Temps de travail':'Temps de récupération'}</div></div></div></div><div class="timer-actions"><button class="primary-btn" data-focus-action="toggle">${uiIcon(focusRun.running?'pause':'play')} ${focusRun.running?'Mettre en pause':focusRun.left<focusRun.duration?'Reprendre':'Démarrer'}</button><button class="secondary-btn" data-focus-action="finish" ${!locked?'disabled':''}>Terminer et enregistrer</button><button class="link-btn" data-focus-reset ${!locked?'disabled':''}>Réinitialiser</button></div></section><aside class="focus-side"><section class="card study-total"><span class="eyebrow">ÉTUDE AUJOURD’HUI</span><div class="hours-total" id="todayHours"></div><p id="dailyCaption"></p><div class="progress-bar"><div class="progress-fill" id="dailyGoal"></div></div></section><section class="card focus-settings"><h2>Session</h2><form id="focusSettings"><div class="field"><label for="sessionObjective">Objectif de la session</label><input id="sessionObjective" maxlength="180" value="${esc(focusRun.objective||settings.objective||'')}" placeholder="Ex. Terminer deux exercices" ${locked?'disabled':''}></div><div class="field"><label for="focusSubject">Matière</label><select name="subject" id="focusSubject" ${locked?'disabled':''}>${subjectOptions()}</select></div><div class="settings-grid">${field('Étude (min)','work','number',`min="1" max="180" value="${settings.work}" ${locked?'disabled':''}`)}${field('Pause (min)','break','number',`min="1" max="60" value="${settings.break}" ${locked?'disabled':''}`)}</div>${field('Objectif quotidien (heures)','goal','number',`min="0.5" max="16" step="0.5" value="${settings.goal}"`)}<button class="secondary-btn" type="submit">Appliquer les réglages</button></form></section></aside></div><section class="card session-history"><div class="section-title-row"><h2>Sessions d’aujourd’hui</h2><span>${todaySessions.length}</span></div>${todaySessions.length?todaySessions.map(s=>`<div class="session-row"><div><strong>${esc(s.subject||'Étude libre')}</strong><small>${esc(s.objective||'Session enregistrée')}</small></div><strong>${studyHours(s.minutes*60)}</strong></div>`).join(''):emptyState('focus','Aucune session enregistrée','Ta première session terminée apparaîtra ici.')}</section>`;
 document.querySelector('#focusSubject').value=focusRun.subject||settings.subject;
 document.querySelector('#focusSettings').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));settings.goal=Number(d.goal);if(!locked){settings.work=Number(d.work);settings.break=Number(d.break);settings.subject=d.subject;focusRun.subject=d.subject;focusRun.duration=settings[focusRun.mode]*60;focusRun.left=focusRun.duration}persistFocus();render();showToast('Réglages enregistrés')};
 updateFocusDisplay();
};
const finishFocusProductBase=finishFocus;
finishFocus=function(){const before=state.focusSessions.length,objective=focusRun.objective||state.focusSettings.objective||'';finishFocusProductBase();state.focusSessions.slice(before).forEach(s=>s.objective=objective);save();if(currentPage==='focus')render()};

function activityDates(){return new Set([...state.focusSessions.filter(s=>s.minutes>0).map(s=>s.date),...state.tasks.filter(t=>t.done).map(t=>t.completedAt),...allChapters().map(c=>c.completedAt)].filter(Boolean))}
function currentStreak(){const dates=activityDates();let d=new Date(),n=0;if(!dates.has(localISO(d)))d.setDate(d.getDate()-1);while(dates.has(localISO(d))){n++;d.setDate(d.getDate()-1)}return n}
let progressRange='week';
renderProgress=function(){
 const dates=dashboardPeriodDates(progressRange),minutes=dates.map(focusMinutesOn),max=Math.max(60,...minutes);
 const total=state.focusSessions.reduce((sum,s)=>sum+Number(s.minutes||0),0);
 const periodTotal=minutes.reduce((a,b)=>a+b,0),recent=[...state.focusSessions.map(s=>({date:s.date,title:`Session · ${s.subject||'Étude libre'}`,meta:studyHours(Number(s.minutes||0)*60)})),...state.tasks.filter(t=>t.done&&t.completedAt).map(t=>({date:t.completedAt,title:t.title,meta:'Tâche terminée'})),...allChapters().filter(c=>c.completedAt).map(c=>({date:c.completedAt,title:c.name,meta:'Chapitre maîtrisé'}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
 const metric=(icon,value,label,caption='')=>`<article class="progress-metric"><span>${uiIcon(icon)}</span><div><strong>${value}</strong><small>${label}</small>${caption?`<em>${caption}</em>`:''}</div></article>`;
 const chart=periodTotal?`<div class="activity-chart ${progressRange==='month'?'monthly':''}">${dates.map((d,i)=>`<div class="activity-bar"><span title="${formatShort(d)} : ${Math.floor(minutes[i])} min" style="height:${Math.max(2,minutes[i]/max*150)}px"></span><small>${d.slice(-2)}</small></div>`).join('')}</div><p class="helper">Temps de concentration réel, hors pauses.</p>`:emptyState('focus','Tes prochaines sessions apparaîtront ici.','Commence une session pour construire ton historique.','<button class="secondary-btn" data-go="focus">Commencer une session</button>');
 document.querySelector('#page').innerHTML=header('Progression','Tes résultats, calculés à partir de ton travail.')+`<section class="progress-section"><div class="section-title-row"><div><span class="eyebrow">VUE D’ENSEMBLE</span><h2>Ton avancée</h2></div></div><div class="progress-overview">${metric('progress',`${progressPercent()} %`,'Programme terminé')}${metric('bolt',`${state.xp} XP`,'Expérience',`Niveau ${level()}`)}${metric('subjects',doneChapters(),'Chapitres terminés')}${metric('tasks',completedTasks(),'Tâches terminées')}${metric('focus',studyHours(total*60),'Temps étudié')}${metric('calendar',`${currentStreak()} j`,'Série en cours')}</div></section><section class="activity-panel progress-study"><div class="activity-panel-head"><div><span class="eyebrow">TEMPS D’ÉTUDE</span><h2>${studyHours(periodTotal*60)} étudiées ${progressRange==='week'?'cette semaine':'ce mois-ci'}</h2></div><div class="view-tabs compact-tabs">${[['week','Semaine'],['month','Mois']].map(([v,l])=>`<button data-progress-range="${v}" aria-pressed="${progressRange===v}" class="${progressRange===v?'active':''}">${l}</button>`).join('')}</div></div>${chart}</section><div class="progress-columns"><section class="activity-panel"><h2>Progression par matière</h2>${state.subjects.length?state.subjects.map(s=>`<div class="mastery-progress-row"><div><strong>${esc(s.name)}</strong><span>${subjectMastery(s)} %</span></div><div class="progress-bar"><div class="progress-fill" style="width:${subjectMastery(s)}%"></div></div></div>`).join(''):emptyState('subjects','Aucune matière à suivre','Ajoute une matière pour voir sa progression.','<button class="secondary-btn" data-go="subjects">Ajouter une matière</button>')}</section><section class="activity-panel"><h2>Activité récente</h2>${recent.length?`<div class="recent-list">${recent.map(item=>`<div class="recent-row"><span>${uiIcon('check')}</span><div><strong>${esc(item.title)}</strong><small>${formatShort(item.date)} · ${esc(item.meta)}</small></div></div>`).join('')}</div>`:emptyState('calendar','Aucune activité récente','Tes sessions, tâches et chapitres terminés apparaîtront ici.')}</section></div>`;
};
function renderAccount(){
 const account=window.PrepagoAccount,p=account?.profile||{};
 const expires=p.subscription_status==='trial'?p.trial_ends_at:p.subscription_ends_at;
 const expiry=expires?new Intl.DateTimeFormat('fr-FR',{dateStyle:'long'}).format(new Date(expires)):'Sans date renseignée';
 document.querySelector('#page').innerHTML=header('Mon compte','Ton profil et ton accès à Prepago.')+`<div class="account-grid"><section class="activity-panel"><h2>Profil étudiant</h2><form id="accountForm"><div class="field"><label for="accountName">Nom complet</label><input id="accountName" name="full_name" maxlength="100" required value="${esc(p.full_name||state.profileName)}"></div><div class="field"><label for="accountEmail">Adresse e-mail</label><input id="accountEmail" type="email" readonly value="${esc(account?.email||'')}"></div><div class="field"><label for="accountFiliere">Filière</label><select id="accountFiliere" name="filiere" required>${!window.PrepagoCurriculum.normalizeTrack(p.filiere)?'<option value="" disabled selected>Choisir une filière CPGE</option>':''}${window.PrepagoCurriculum.tracks.map(track=>`<option value="${track.id}" ${window.PrepagoCurriculum.normalizeTrack(p.filiere)===track.id?'selected':''}>${track.label}</option>`).join('')}</select><p class="helper">Les deux années sont incluses. Ton travail reste conservé pour chaque filière.</p></div><button class="primary-btn" type="submit">Enregistrer le profil</button><p id="accountMessage" role="status"></p></form></section><section class="activity-panel"><h2>Abonnement</h2><dl class="account-details"><dt>Formule</dt><dd>${p.subscription_plan==='ai_plus'?'Prepago AI+':'Prepago'}</dd><dt>Statut</dt><dd>${esc(account?.statusLabel(p)||'Inactif')}</dd><dt>Fin de l’accès</dt><dd>${esc(expiry)}</dd><dt>Accès promo</dt><dd>${p.subscription_status==='promo'?'Activé':'Non'}</dd></dl><p class="helper">Tes données restent conservées après l’expiration de ton accès.</p><button class="secondary-btn" data-account-logout>Se déconnecter</button></section><section class="activity-panel"><h2>Modifier mon mot de passe</h2><form id="accountPasswordForm"><div class="field"><label for="accountCurrentPassword">Mot de passe actuel</label><input id="accountCurrentPassword" name="current_password" type="password" autocomplete="current-password" required></div><div class="field"><label for="accountNewPassword">Nouveau mot de passe</label><input id="accountNewPassword" name="password" type="password" autocomplete="new-password" minlength="8" required></div><div class="field"><label for="accountConfirmPassword">Confirmer le nouveau mot de passe</label><input id="accountConfirmPassword" name="confirmation" type="password" autocomplete="new-password" minlength="8" required></div><button class="primary-btn" type="submit">Enregistrer le mot de passe</button><p id="accountPasswordStatus" role="status"></p></form></section></div>`;
 document.querySelector('#accountForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button'),msg=document.querySelector('#accountMessage');b.disabled=true;msg.textContent='Enregistrement…';try{await account.update(Object.fromEntries(new FormData(e.target)));navigate('account');document.querySelector('#accountMessage').textContent='Profil enregistré.'}catch{msg.textContent='Impossible d’enregistrer le profil. Vérifie ta connexion.'}finally{b.disabled=false}};
 document.querySelector('#accountPasswordForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),status=document.querySelector('#accountPasswordStatus');if(button.disabled)return;const values=Object.fromEntries(new FormData(e.target));if(values.password!==values.confirmation){status.textContent='Les deux mots de passe ne correspondent pas.';return}button.disabled=true;status.textContent='Enregistrement…';try{await account.changePassword(values);e.target.reset();status.textContent='Mot de passe mis à jour.'}catch(error){status.textContent=account.friendlyError(error)}finally{button.disabled=false}};
 window.PrepagoPromos?.controls();
}
function renderAI(){document.querySelector('#page').innerHTML=header('AI Planner','Ton futur assistant de révision.')+`<section class="activity-panel ai-placeholder"><span class="tag">Bientôt</span><span class="ai-mark">${uiIcon('bolt')}</span><h2>Prepago AI+ arrive bientôt.</h2><p>Des plans d’étude personnalisés et des recommandations adaptées à ta progression sont en préparation.</p><p>Aucun service d’IA n’est encore connecté et aucune facturation AI+ n’est effectuée.</p><button class="secondary-btn" data-go="account">Voir mon abonnement</button></section>`}
const renderProductBase=render;
render=function(){if(currentPage==='account')renderAccount();else if(currentPage==='ai')renderAI();else renderProductBase();document.body.dataset.page=currentPage;document.querySelectorAll('.nav-item').forEach(n=>{const active=n.dataset.page===currentPage;n.classList.toggle('active',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});refreshIcons();updateSidebar()};
document.addEventListener('click',e=>{
 const rename=e.target.closest('[data-rename-subject]');if(rename){const s=state.subjects.find(s=>s.id===rename.dataset.renameSubject);openModal('Renommer la matière',field('Nom','name','text',`maxlength="100" value="${esc(s.name)}"`),d=>{const old=s.name;s.name=d.name.trim();state.tasks.forEach(t=>{if(t.subject===old)t.subject=s.name});state.focusSessions.forEach(t=>{if(t.subject===old)t.subject=s.name});if(state.focusSettings.subject===old)state.focusSettings.subject=s.name;if(focusRun.subject===old)focusRun.subject=s.name})}
 const chapter=e.target.closest('[data-rename-chapter]');if(chapter){const c=allChapters().find(c=>c.id===chapter.dataset.renameChapter);openModal('Renommer le chapitre',field('Nom','name','text',`maxlength="150" value="${esc(c.name)}"`),d=>c.name=d.name.trim())}
 if(e.target.closest('[data-calendar-task]')){taskEditor();document.querySelector('#modalForm').elements.date.value=selectedDay}
 const preset=e.target.closest('[data-focus-preset]');if(preset&&!preset.disabled){state.focusSettings.work=Number(preset.dataset.focusPreset);focusRun.mode='work';focusRun.duration=focusRun.left=state.focusSettings.work*60;persistFocus();render()}
 if(e.target.closest('[data-focus-reset]')&&confirm('Réinitialiser le chrono ? Le temps déjà étudié sera enregistré.')){settleFocus();finishFocus();render()}
 const range=e.target.closest('[data-progress-range]');if(range){progressRange=range.dataset.progressRange;render()}
 if(e.target.closest('[data-account-logout]'))window.PrepagoAccount?.signOut();
 const finished=e.target.closest('[data-chapter-finish]');if(finished){const c=allChapters().find(c=>c.id===finished.dataset.chapterId);if(c){c.completedAt=c.done?todayISO():null;save()}}
});
document.addEventListener('input',e=>{if(e.target.id==='sessionObjective'){state.focusSettings.objective=e.target.value;focusRun.objective=e.target.value;persistFocus()}});
// Score input must not silently store values outside /20.
document.addEventListener('input',e=>{if(e.target.id==='paperScore'){const p=getPaper(cncView.filiere,cncView.subject,cncView.year);if(!e.target.checkValidity()){p.score='';e.target.setAttribute('aria-invalid','true');showToast('La note doit être comprise entre 0 et 20.')}else e.target.removeAttribute('aria-invalid');save()}});
setInterval(()=>{if(!document.body.classList.contains('auth-pending')&&['overview','progress'].includes(currentPage)&&focusRun.running&&document.querySelector('#modalBackdrop').hidden)render()},15000);
render();
